"use server";

/**
 * Updates issue fields.
 *
 * Owner D. Only the fields present in the payload are touched; the service
 * diffs them and emits `issue.updated` with `changedFields` so the activity log
 * can describe the edit without re-reading the row.
 *
 * Must call (do not reimplement): updateIssueSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateIssueSchema, type UpdateIssueInput } from "@/schemas/issue";
import { updateIssue } from "@/server/services/issue-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";

const run = withAction<typeof updateIssueSchema, Issue>(
  updateIssueSchema,
  async (raw, actor) => {
    const input = raw as UpdateIssueInput;

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: input.issueId,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:update");
    }

    const issue = await updateIssue(actor, input);
    revalidateTagged([issueTag(issue.id)], CACHE_PROFILES.seconds);
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "seconds" },
);

export async function updateIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
"use server";

/**
 * Board drag-and-drop target; reconciles the optimistic update.
 *
 * Owner D. The client has already moved the card via `useOptimisticIssues`, so
 * the only thing that matters here is returning the authoritative row — the
 * hook reconciles against it and snaps the card back if the move was refused.
 * Dragging is only reachable when `kanban_board` is on, and the flag is
 * re-checked server-side because the client copy is only a snapshot.
 *
 * Must call (do not reimplement): moveIssueSchema, can, isEnabled, getActor,
 * toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
} from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { moveIssueSchema, type MoveIssueInput } from "@/schemas/issue";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { moveIssue } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";

const run = withAction<typeof moveIssueSchema, Issue>(
  moveIssueSchema,
  async (raw, actor) => {
    const input = raw as MoveIssueInput;

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: input.issueId,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:update");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("kanban_board", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("kanban_board");
    }

    const issue = await moveIssue(actor, input);
    revalidateTagged(
      [issueTag(issue.id), projectTag(issue.projectId)],
      CACHE_PROFILES.seconds,
    );
    return issue;
  },
  { revalidate: ["board"], cacheProfile: "seconds" },
);

export async function moveIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
"use server";

/**
 * Archives an issue (soft delete).
 *
 * Owner D. `assertNotArchived()` makes the operation fail loudly rather than
 * silently re-stamping `archived_at`, which would otherwise reset the retention
 * clock the cleanup job reads.
 *
 * Must call (do not reimplement): archiveIssueSchema, can, assertNotArchived,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { archiveIssueSchema } from "@/schemas/issue";
import { archiveIssue, getIssue } from "@/server/services/issue-service";
import type { ActionResult } from "@/types/api";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue } from "@/types/issue";

type ArchiveIssueInput = { orgId: OrgId; issueId: IssueId };

const run = withAction<typeof archiveIssueSchema, Issue>(
  archiveIssueSchema,
  async (raw, actor) => {
    const input = raw as ArchiveIssueInput;

    const current = await getIssue(actor, input.orgId, input.issueId);

    const allowed = can(actor, "issue:archive", {
      kind: "issue",
      orgId: input.orgId,
      projectId: current.issue.projectId,
      issueId: input.issueId,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:archive");
    }

    assertNotArchived("issue", input.issueId, current.issue);

    const issue = await archiveIssue(actor, input.orgId, input.issueId);
    revalidateTagged(
      [issueTag(issue.id), projectTag(issue.projectId)],
      CACHE_PROFILES.minutes,
    );
    return issue;
  },
  { revalidate: ["issues", "board"], cacheProfile: "minutes" },
);

export async function archiveIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}

