/**
 * The sub-issue tree invariant: no loops, and nothing sits deeper than
 * `MAX_SUB_ISSUE_DEPTH`. `IssueService` is the only caller — this module just
 * names the failure.
 */

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its own sub-issues.`
        : `Issue ${issueId} would sit deeper than the maximum allowed depth.`,
    );
    this.name = "IssueHierarchyError";
  }
}

