/**
 * Every direct child, structurally — archived or not. The tree-shape guards
 * (cycle, depth) reason over the whole tree, not just the live slice of it.
 */
export async function listChildren(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.parentId, parentId)),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

/** Direct, live sub-issues, oldest first (creation time, then issue number). */
export async function listLiveChildren(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.createdAt, issues.number)
    .all();
  return rows.map((row) => toIssue(row));
}

/** Counts every live descendant, at any depth, by open/closed status. */
export async function getDescendantRollup(
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  let total = 0;
  let open = 0;
  let closed = 0;

  const queue: IssueId[] = [issueId];
  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    const children = await listChildren(orgId, current);
    for (const child of children) {
      queue.push(child.id);
      if (child.archivedAt !== null) continue;
      total += 1;
      if (CLOSED_ISSUE_STATUSES.includes(child.status)) {
        closed += 1;
      } else {
        open += 1;
      }
    }
  }

  return { total, open, closed };
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */

