/**
 * Places, moves or roots an issue. Guards, in order: the issue itself must be
 * live; a non-null target must be a live issue of the same project; the move
 * must not create a cycle; and the issue's deepest descendant must not land
 * past `MAX_SUB_ISSUE_DEPTH`. A no-op (same parent) returns the issue as-is.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.parentId === input.parentId) {
    return before;
  }

  if (input.parentId !== null) {
    const parent = await assertValidParent(
      input.orgId,
      before.projectId,
      input.parentId,
    );

    if (
      parent.id === before.id ||
      (await isDescendant(input.orgId, before.id, parent.id))
    ) {
      throw new IssueHierarchyError(before.id, "cycle");
    }

    const parentLevel = await levelOf(input.orgId, parent.id);
    const height = await subtreeHeight(input.orgId, before.id);
    if (parentLevel + 1 + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(before.id, "too_deep");
    }
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

export async function listSubIssues(
  actor: Actor,
