/** A non-null parent must be a live issue of the same project. */
async function assertValidParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/** True when `candidateId` sits anywhere below `ancestorId`, at any depth. */
async function isDescendant(
  orgId: OrgId,
  ancestorId: IssueId,
  candidateId: IssueId,
): Promise<boolean> {
  const children = await issueRepo.listChildren(orgId, ancestorId);
  for (const child of children) {
    if (child.id === candidateId) return true;
    if (await isDescendant(orgId, child.id, candidateId)) return true;
  }
  return false;
}

/** Root is level 0; each step down the parent chain adds one. */
async function levelOf(orgId: OrgId, issueId: IssueId): Promise<number> {
  let level = 0;
  let current = await issueRepo.findIssueById(orgId, issueId);
  while (current && current.parentId !== null) {
    current = await issueRepo.findIssueById(orgId, current.parentId);
    level += 1;
  }
  return level;
}

/** 0 for a leaf; otherwise one more than its deepest child's height. */
async function subtreeHeight(orgId: OrgId, issueId: IssueId): Promise<number> {
  const children = await issueRepo.listChildren(orgId, issueId);
  if (children.length === 0) return 0;

  const heights = await Promise.all(
    children.map((child) => subtreeHeight(orgId, child.id)),
  );
  return 1 + Math.max(...heights);
}

