async function notifyParentIfFullyClosed(
  orgId: OrgId,
  issueId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue || issue.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

